636	func (s *FileServerService) getMotionPath(attachment *store.Attachment) (string, error) {
637		cacheFolder := filepath.Join(s.Profile.Data, MotionCacheFolder)
638		if err := os.MkdirAll(cacheFolder, os.ModePerm); err != nil {
639			return "", errors.Wrap(err, "failed to create motion cache folder")
640		}
641	
642		return filepath.Join(cacheFolder, attachment.UID+".mp4"), nil
643	}
